const Perk=require("../models/perksModel"),ShopItem=require("../models/shopItemModel"),handleErrors=require("../utilities/handle_errors")["handleErrors"],create_shopItem=(t,s,e)=>{ShopItem.create(t.body).then(e=>{s.status(200).send(e)}).catch(e=>{s.status(422).send(handleErrors(e,t,"shopItem"))})},get_shopItems=async(e,d,t)=>{const o=await Perk.find({});ShopItem.find({}).then(e=>{var t=o,s=e.filter(e=>"coins"===e.itemType),e=e.filter(e=>"bundles"===e.itemType);d.status(200).send({perks:t,coins:s,bundles:e})}).catch(t)},get_admin_shopItems=(e,s,d)=>{const o=e.query.page-1||0;ShopItem.find({}).count().then(t=>{ShopItem.find({}).skip(30*o).limit(30).then(e=>s.status(200).send({shopItems:e,total_shopItems:t,per_page:30})).catch(d)})},get_single_shopItem=(e,t,s)=>{ShopItem.findById({_id:e.params.id}).then(e=>t.status(200).send(e)).catch(s)},update_shopItem=(t,s,e)=>{ShopItem.findByIdAndUpdate({_id:t.params.id},t.body).then(e=>{ShopItem.findOne({_id:t.params.id}).then(e=>s.status(200).send(e))}).catch(e)},delete_shopItem=(e,t,s)=>{ShopItem.findByIdAndDelete({_id:e.params.id}).then(e=>{t.status(200).send(e)}).catch(s)};module.exports={create_shopItem:create_shopItem,update_shopItem:update_shopItem,get_single_shopItem:get_single_shopItem,get_admin_shopItems:get_admin_shopItems,get_shopItems:get_shopItems,delete_shopItem:delete_shopItem};